"""Self-contained English scientific HTML from saved outputs only."""
import base64,html,json
from pathlib import Path
import pandas as pd


def generate(root,config,run,out,summary,profiles):
    n=summary['network'];go=summary['GO'];og=summary['orthogroup'];p=n['primary'];w=n['weighted']
    qc=json.loads((run/'01_interactions/qc_summary.json').read_text())
    candidates=pd.read_csv(run/'01_interactions/interaction_evidence.tsv',sep='\t')
    self_count=len(pd.read_csv(run/'02_network/self_evidence.tsv',sep='\t'))
    allpairs=pd.read_csv(run/'01_interactions/physical_organism_pairs.tsv',sep='\t')
    wormhuman=int(allpairs[((allpairs.taxon_A==6239)&(allpairs.taxon_B==9606))|((allpairs.taxon_A==9606)&(allpairs.taxon_B==6239))].records.sum())
    status=pd.DataFrame(summary['evidence']);bio=run/'05_biological_evidence'
    blastmeta=json.loads((bio/'blast/source_manifest.json').read_text()) if (bio/'blast/source_manifest.json').exists() else {}
    def table(df):return '<div class="table-wrap">'+df.to_html(index=False,escape=True,na_rep='NA',border=0,classes='data-table')+'</div>'
    def fig(name):
        data=(out/'figures'/f'{name}.svg').read_bytes();meta=json.loads((out/'figure_manifests'/f'{name}.json').read_text())
        return f'<figure><img src="data:image/svg+xml;base64,{base64.b64encode(data).decode()}" alt="{html.escape(meta["caption"])}"><figcaption>{html.escape(meta["caption"])}</figcaption></figure>'
    source=table(status[['source','status','records','database_version','retrieved_at','reason']])
    comm=pd.read_csv(run/'04_functional_context/community_go_summary.tsv',sep='\t',keep_default_na=False)
    hubs=profiles[['WBGene','Gene_symbol','UniProt','community','degree','hub_frequency','wormbase_status','bgee_status','blast_status','blast_hits','best_human_UniProt','best_evalue','best_query_coverage','best_subject_coverage']].copy()
    # Keep full numerical precision in TSV; HTML format is for reading only.
    for col in ['hub_frequency','best_query_coverage','best_subject_coverage']:
        if col in hubs:hubs[col]=pd.to_numeric(hubs[col],errors='coerce').round(2)
    title='Protein–Protein Interaction Network Analysis for Antiparasitic Target Prioritization'
    text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title>
<style>
:root{{--ink:#162e3d;--muted:#536c7c;--teal:#126e76;--line:#d7e2e7;--paper:#fff;--bg:#edf3f5}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:17px/1.65 Arial,Helvetica,sans-serif}}header{{background:#113b4b;color:white;padding:56px max(6vw,24px) 42px}}header p{{max-width:850px;color:#c7dfe4}}h1{{font:600 clamp(28px,4vw,48px)/1.15 Georgia,serif;max-width:1100px;margin:12px 0 22px}}.eyebrow{{text-transform:uppercase;letter-spacing:.18em;font-size:12px;color:#9ed0cf}}nav{{position:sticky;top:0;z-index:5;background:white;border-bottom:1px solid var(--line);padding:12px 6vw;display:flex;gap:23px;flex-wrap:wrap}}a{{color:var(--teal)}}nav a{{text-decoration:none;font-size:14px;font-weight:bold}}main{{max-width:1200px;margin:26px auto;padding:0 26px 50px}}section{{background:white;padding:30px 38px;margin:20px 0;border:1px solid var(--line);border-radius:5px;scroll-margin-top:90px}}h2{{font:600 29px/1.3 Georgia,serif;margin:0 0 18px}}h3{{font-size:18px;margin:28px 0 8px}}p{{max-width:1000px}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:24px 0}}.metric{{background:white;padding:20px;border-top:4px solid var(--teal)}}.metric strong{{display:block;font-size:32px}}.metric span{{font-size:13px;color:var(--muted)}}.notice{{border-left:4px solid #bf8334;background:#fff7e8;padding:16px 20px;font-size:15px}}.table-wrap{{overflow-x:auto;max-width:100%;margin:18px 0}}table{{border-collapse:collapse;width:100%;font-size:12px;line-height:1.45}}th,td{{padding:10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}}th{{background:#eaf2f4;white-space:nowrap}}tbody tr:nth-child(even){{background:#f7fafb}}figure{{margin:24px 0 35px;text-align:center}}figure img{{max-width:100%;width:850px;height:auto}}figcaption{{text-align:left;font-size:14px;color:var(--muted);border-top:1px solid var(--line);padding-top:12px}}code{{font-size:13px;overflow-wrap:anywhere}}.small{{font-size:13px;color:var(--muted)}}input{{padding:12px;width:min(500px,100%);border:1px solid #91aab7;border-radius:4px}}footer{{font-size:13px;color:var(--muted);padding:24px}}@media(max-width:700px){{section{{padding:22px 17px}}main{{padding:0 12px}}.metrics{{grid-template-columns:repeat(2,1fr)}}nav{{gap:12px}}}}@media print{{nav{{display:none}}body{{background:white}}section{{border:0;padding:10px 0;break-inside:auto}}header{{background:white;color:black;padding:20px 0}}header p{{color:#333}}figure{{break-inside:avoid}}.table-wrap{{overflow:visible}}}}
</style></head><body><header><div class="eyebrow">Local analysis report · reproducible candidate profiles</div><h1>{title}</h1><p>Physical interactions, community-level function and independent biological evidence in <i>Caenorhabditis elegans</i>. This report supports candidate prioritization; it does not establish essentiality, druggability, selectivity or therapeutic efficacy.</p><div class="small" style="color:#c7dfe4">Run {html.escape(run.name)} · English report · local results, excluded from the public pipeline repository</div></header>
<nav><a href="#abstract">Abstract</a><a href="#methods">Methods</a><a href="#results">Results</a><a href="#evidence">Evidence</a><a href="#profiles">Candidates</a><a href="#limitations">Limitations</a><a href="#availability">Reproducibility</a></nav><main>
<div class="metrics"><div class="metric"><strong>{n['lcc_nodes']}</strong><span>LCC genes</span></div><div class="metric"><strong>{n['lcc_edges']}</strong><span>LCC physical edges</span></div><div class="metric"><strong>{p['communities']}</strong><span>Primary communities</span></div><div class="metric"><strong>{p['robust_hubs']}</strong><span>Robust candidates</span></div></div>
<section id="abstract"><h2>Abstract</h2><p><b>Objective.</b> To organize physical interaction evidence associated with an investigator-provided set of <i>C. elegans</i> genes into traceable candidate target profiles. <b>Methods.</b> BioGRID physical records were restricted to two taxon-6239 interactors and at least one input gene. A WBGene-based simple graph was reduced to one largest connected component (LCC). Unweighted centrality, consensus Louvain communities and perturbation-stable degree hubs formed the primary analysis. Publication-weighted analysis assessed sensitivity on identical nodes and edges. Community GO enrichment and independent expression and human sequence-similarity evidence provided biological context. <b>Results.</b> The LCC contained {n['lcc_nodes']} genes and {n['lcc_edges']} edges, with {p['communities']} primary communities and {p['robust_hubs']} robust hubs. There were {go['significant_BP']} significant community–Biological Process associations across {go['communities_with_significant_BP']} communities. Bgee evidence was available for {summary['Bgee_hubs_with_records']} candidates; {summary['BLAST_hubs_with_hits']} candidates had at least one reported human sequence-similarity hit. <b>Interpretation.</b> These profiles provide an auditable basis for further prioritization. WormBase evidence is deferred, and human similarity is not orthology or demonstrated host toxicity.</p><div class="notice"><b>Incomplete evidence, explicitly preserved:</b> WormBase was not run in this analysis following an earlier HTTP 403 access failure and the user's instruction to defer integration. Phenotype and essentiality fields are unavailable, not negative.</div></section>
<section id="methods"><h2>Materials and methods</h2><h3>Input and interaction discovery</h3><p>The unmodified input comprised {qc['valid_rows']} WBGene–UniProt records, {qc['unique_WBGene']} unique genes and {qc['unique_UniProt']} unique protein accessions. Counts were computed from the data, not encoded in the scientific logic. Valid many-to-one accession mappings were preserved without node merging. Orthogroup annotation was {html.escape(og['orthogroup_annotation'])}; it is optional metadata and never defines a network node.</p><p>BioGRID 5.0.262 was acquired on 15 October 2026; NCBI gene_info cross-references were acquired on 16 October 2026. The complete organism file was characterized before selecting candidates. Both <code>Organism ID Interactor A/B</code> had to equal 6239 and <code>Experimental System Type</code> had to be physical. Entrez identifiers were resolved to unambiguous WBGene IDs. Only records incident to an original input gene were included; there was no recursive expansion or addition of edges solely between external partners.</p><h3>Topology and primary prioritization</h3><p>Self-interactions were preserved as evidence and excluded from the simple undirected topology. Repeated evidence was collapsed into one unordered gene pair while retaining records, publications and systems. Input isolates were retained in the full graph. One LCC was selected by largest node count, with a deterministic identifier tie-break. Exact normalized betweenness, closeness, degree, degree centrality, PageRank (α=0.85), eigenvector centrality and k-core were computed. Eigenvector iteration used a maximum of 3,000 iterations and tolerance 10⁻¹⁰; PageRank used 100 iterations and tolerance 10⁻⁶.</p><p>Louvain was run for seeds 0–99 at resolution 1.0. Pairwise coassignment ≥0.5 defined a weighted consensus graph; Louvain seed 0 on that graph defined the principal partition. A further 100 consensus runs characterized stability. Primary hubs were nodes with degree at or above the empirical 95th percentile (linear interpolation, including ties). Across 100 paired perturbations retaining 90% of edges, all LCC nodes were retained and the threshold recalculated. A robust hub had to be an original hub and recur in at least 90% of perturbations. The perturbation seed was 20260806.</p><h3>Weighted sensitivity and functional context</h3><p>Distinct publications per edge defined documentary support. Weighted PageRank, eigenvector centrality and Louvain used support; shortest-path metrics used a separate distance of 1/support. Both analyses used the exact same base LCC. Sensitivity hubs used strength instead of degree with the same percentile and stability criteria. Resolution, source-deletion and quantile diagnostics were saved separately.</p><p>GO used the current project snapshot of CAEEL-mod GAF (generated 4 August 2026) and go-basic OBO (26 July 2026). Positive LCC terms were validated for existence, active status and matching ontology aspect; NOT annotations were excluded. Direct annotations, including IEA, were used without propagation. The reference universe was all {n['lcc_nodes']} LCC genes, including unannotated genes. One-sided Fisher tests were performed for a fixed family of {go['family_terms']} P/F/C terms, including zero-overlap tests. Benjamini–Hochberg correction was applied within each community across that family. BP terms with FDR&lt;0.05 were displayed; top terms were ordered by FDR, raw p and GO ID. Network-level annotation coverage describes the whole LCC; enrichment was not restricted to hubs.</p><h3>Independent candidate evidence</h3><p>Bgee 15.2 advanced all-condition calls were acquired on 16 October 2026 and filtered to candidate WBGene IDs. Present, absent, missing records, quality and propagated evidence remain distinct. No high-expression threshold was imposed. Query proteins were retrieved from UniProt 2026_03 using the unique current GeneID reference and validated species/gene cross-references. Canonical sequences and available named isoforms were preserved.</p><p>BLASTP 2.17.0+ searched {blastmeta.get('query_sequence_count','NA')} exact query sequences against {blastmeta.get('target_sequence_count',0):,} sequences from the human reference proteome UP000005640, including reviewed/unreviewed entries and available isoforms. Settings were E≤10⁻⁵, BLOSUM62, gap opening/extension 11/1, word size 3, composition statistics 2, SEG enabled, soft masking disabled and four threads. All qualifying subjects were retained up to the full target count. No additional identity/coverage cutoff or reciprocal search was applied. Coverage is the union of aligned coordinates divided by full sequence length; identity and alignment length describe the best HSP. Full sequences, commands, database metadata and raw HSPs remain local.</p></section>
<section id="results"><h2>Results</h2><h3>From raw evidence to one LCC</h3><p>The species file contained {qc['source_records']:,} records: {qc['source_types'].get('physical',0):,} physical and {qc['source_types'].get('genetic',0):,} genetic. Among all physical records, {qc['source_physical_cross_species']} were cross-species, including {wormhuman} worm–human records. These were preserved for QC and excluded from topology. Of the input genes, {qc['input_with_physical']} had a matching physical record and {qc['input_without_physical']} did not. The input-associated physical subset contained {qc['candidate_physical_records']:,} records. {qc['excluded_physical_records']} records were excluded by organism/identity validation and {self_count} were self-records; the remaining {qc['resolved_physical_records']-self_count:,} evidence records represented {n['full_edges']:,} distinct pairs.</p><p>The full graph contained {n['full_nodes']} nodes and {n['full_edges']} edges, including {n['isolates']} isolates across {n['components']} components. The LCC contained {n['input_in_LCC']} original input genes and {n['lcc_nodes']-n['input_in_LCC']} external partner genes. Density was {n['density']:.5f}, mean degree {n['mean_degree']:.3f}, mean shortest path {n['average_shortest_path']:.3f} and diameter {n['diameter']}. These are properties of a candidate-incident sampling design, not of the complete worm interactome.</p>{fig('figure_A_network')}<h3>Community structure and robustness</h3><p>The principal partition had {p['communities']} communities and modularity {p['modularity']:.3f}. Seed-level mean pairwise ARI was {p['mean_seed_pairwise_ARI']:.3f}. The consensus graph yielded {p['consensus_distinct_partitions']} distinct partitions across consensus seeds; the documented seed-0 partition was retained. The degree threshold was {p['hub_threshold']:g}, producing {p['original_hubs']} initial hubs and {p['robust_hubs']} robust candidates.</p><p>Weighted sensitivity produced {w['communities']} communities and {w['robust_hubs']} robust hubs. Primary–weighted community ARI was {n['community_ARI_primary_weighted']:.3f}; {n['robust_hub_overlap']} robust hubs were shared. Publication support therefore changes some memberships and rankings while preserving most selected hubs. Degree correlated with publication count (Spearman ρ={n['study_bias_Spearman']['publications']:.3f}), so documentation/study bias remains relevant.</p>{fig('figure_C_sensitivity')}<h3>Functional context</h3><p>{go['mapped_background_genes']} of {go['background_genes']} LCC genes had direct positive annotations ({100*go['mapped_background_genes']/go['background_genes']:.1f}% coverage). Across {go['total_audit_tests']:,} auditable community–term tests, {go['significant_all_aspects']} associations across all aspects and {go['significant_BP']} BP associations met FDR&lt;0.05. These counts are associations, not necessarily distinct GO terms.</p>{fig('figure_B_community_GO')}{table(comm[['community','nodes','mapped_genes','significant_BP_terms','top3_terms']])}</section>
<section id="evidence"><h2>Evidence availability</h2>{source}<p>Bgee returned expression records for {summary['Bgee_hubs_with_records']} candidates. Condition counts reflect data coverage and ontology aggregation; they do not measure essentiality or independent experimental replication. Human similarity was reported for {summary['BLAST_hubs_with_hits']} candidates; {summary['BLAST_hubs_without_hits']} had no hit meeting the selected reporting threshold. A no-hit result is conditional on the sequences, target and search settings, not proof of no human homolog. Large hit counts can reflect repeated domains, paralogs and isoforms.</p><h3>Completing WormBase later</h3><p>Use the exact {len(profiles)} WBGene IDs in <a href="../05_biological_evidence/wormbase_manual_genes.tsv">wormbase_manual_genes.tsv</a>. A <a href="../05_biological_evidence/wormbase_manual_evidence_template.tsv">manual evidence template</a> is supplied. Batch export via <a href="https://wormmine.alliancegenome.org/wormmine/begin.do">WormMine</a> is preferable to copying genes individually when available. The <a href="https://www.alliancegenome.org/">Alliance</a> provides another potential access route, but release, phenotype coverage and evidence semantics must be checked before substitution. Browser/manual collection is a fallback, not a requirement.</p><p>For every annotation record the WBGene, phenotype ID/label, observed versus explicitly not observed, RNAi versus mutant/allele evidence, supporting reference, source URL, release and retrieval date. Preserve raw exports or page evidence. Do not infer non-essentiality from a missing lethal phenotype. No alternative WormBase source has been integrated in this run.</p></section>
<section id="profiles"><h2>Candidate target profiles</h2><p>One row corresponds to one WBGene. The full <a href="candidate_target_profiles.tsv">candidate profile table</a> preserves all metrics and source statuses; the compact view below is searchable. No global target score has been calculated.</p><input id="filter" type="search" placeholder="Filter by WBGene, symbol or protein accession" aria-label="Filter candidate table"><div id="candidate-table">{table(hubs)}</div></section>
<section id="limitations"><h2>Discussion and limitations</h2><p>Robustness here means persistence under the specified edge-subsampling model. It does not establish biological essentiality. The network is restricted to interactions incident to input genes; external–external edges are systematically absent. Hubs may therefore reflect both sampling design and study intensity. BioGRID physical classifications include diverse assays and do not uniformly imply direct binary contact.</p><p>GO results depend on incomplete annotation, direct rather than propagated associations, the LCC background and the chosen multiple-testing family. GO component dates differ and are reported explicitly; compatibility checks validated the annotations used. Bgee condition coverage is uneven. BLAST similarity alone establishes neither orthology nor host toxicity, and a lack of hits cannot demonstrate parasite selectivity. Missing WormBase evidence is a substantive limitation. Optional orthogroups are currently unavailable and have not been inferred from file names or counts.</p><p>The endpoint is an interpretable set of candidate target profiles. The pipeline does not discover drugs, demonstrate druggability or include experimental validation as an analysis stage.</p></section>
<section id="availability"><h2>Reproducibility and local data availability</h2><p>This self-contained report embeds the figures and performs no external queries. PDF, SVG and 400-dpi PNG versions are in <code>figures/</code>. Figure manifests record inputs, checksums and fonts. Detailed output tables, immutable source snapshots, exact FASTA, raw BLAST output and the run manifest are retained locally. Only source code, documentation, example configuration and synthetic tests are intended for the public GitHub repository.</p><p>Run manifest: <a href="../run_manifest.json">run_manifest.json</a>. Evidence completeness: <a href="evidence_completeness.tsv">evidence_completeness.tsv</a>. Analysis summary: <a href="analysis_summary.json">analysis_summary.json</a>.</p><p class="small">Sources: <a href="https://thebiogrid.org/">BioGRID</a> · <a href="https://geneontology.org/">Gene Ontology</a> · <a href="https://www.bgee.org/">Bgee</a> · <a href="https://www.uniprot.org/">UniProt</a> · <a href="https://blast.ncbi.nlm.nih.gov/">NCBI BLAST</a>. Exact versions and retrieval records are in local manifests.</p></section>
<footer>Generated from saved analysis results. Candidate prioritization only. No claims of validated targets, druggability or therapeutic effect.</footer></main><script>document.getElementById('filter').addEventListener('input',function(){{const q=this.value.toLowerCase();document.querySelectorAll('#candidate-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}});</script></body></html>'''
    (out/'analysis_report.html').write_text(text)
